PRAGMA threads=3; PRAGMA cache_size=100; CREATE TABLE result(run INTEGER NOT NULL,a,c0,c2,c3,c4,c5,c6,b); CREATE TABLE state(run INTEGER NOT NULL,n INTEGER NOT NULL); INSERT INTO state VALUES(0,0); CREATE VIEW sink AS SELECT a,c0,c2,c3,c4,c5,c6,b FROM result; CREATE TRIGGER sink_insert INSTEAD OF INSERT ON sink WHEN (SELECT n FROM state)<1000 BEGIN INSERT INTO result(run,a,c0,c2,c3,c4,c5,c6,b) VALUES((SELECT run FROM state),NEW.a,NEW.c0,NEW.c2,NEW.c3,NEW.c4,NEW.c5,NEW.c6,NEW.b); UPDATE state SET n=n+1; END; UPDATE state SET run=1,n=0; INSERT INTO sink(a,c0,c2,c3,c4,c5,c6,b) SELECT a,c0,c2,c3,c4,c5,c6,b FROM t1 WHERE rowid<=100000 ORDER BY a; UPDATE state SET run=2,n=0; INSERT INTO sink(a,c0,c2,c3,c4,c5,c6,b) SELECT a,c0,c2,c3,c4,c5,c6,b FROM t1 WHERE rowid<=100000 ORDER BY a; UPDATE state SET run=3,n=0; INSERT INTO sink(a,c0,c2,c3,c4,c5,c6,b) SELECT a,c0,c2,c3,c4,c5,c6,b FROM t1 WHERE rowid<=100000 ORDER BY a; UPDATE state SET run=4,n=0; INSERT INTO sink(a,c0,c2,c3,c4,c5,c6,b) SELECT a,c0,c2,c3,c4,c5,c6,b FROM t1 WHERE rowid<=100000 ORDER BY a; UPDATE state SET run=5,n=0; INSERT INTO sink(a,c0,c2,c3,c4,c5,c6,b) SELECT a,c0,c2,c3,c4,c5,c6,b FROM t1 WHERE rowid<=100000 ORDER BY a; UPDATE state SET run=6,n=0; INSERT INTO sink(a,c0,c2,c3,c4,c5,c6,b) SELECT a,c0,c2,c3,c4,c5,c6,b FROM t1 WHERE rowid<=100000 ORDER BY a; UPDATE state SET run=7,n=0; INSERT INTO sink(a,c0,c2,c3,c4,c5,c6,b) SELECT a,c0,c2,c3,c4,c5,c6,b FROM t1 WHERE rowid<=100000 ORDER BY a; UPDATE state SET run=8,n=0; INSERT INTO sink(a,c0,c2,c3,c4,c5,c6,b) SELECT a,c0,c2,c3,c4,c5,c6,b FROM t1 WHERE rowid<=100000 ORDER BY a; UPDATE state SET run=9,n=0; INSERT INTO sink(a,c0,c2,c3,c4,c5,c6,b) SELECT a,c0,c2,c3,c4,c5,c6,b FROM t1 WHERE rowid<=100000 ORDER BY a; UPDATE state SET run=10,n=0; INSERT INTO sink(a,c0,c2,c3,c4,c5,c6,b) SELECT a,c0,c2,c3,c4,c5,c6,b FROM t1 WHERE rowid<=100000 ORDER BY a;